import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import API from "../services/api";

function Devices() {
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newDevice, setNewDevice] = useState({ name: '', powerLimit: 1000, autoOffMinutes: 5 });

  useEffect(() => {
    fetchDevices();
  }, []);

  const fetchDevices = async () => {
    try {
      const res = await API.get("/device").catch(e => ({ data: [
        { _id: '1', name: 'Nexus HVAC Core', status: 'ON', powerLimit: 2100, autoOffMinutes: 10, apiKey: 'mock-key-1' },
        { _id: '2', name: 'EV Charger Unit', status: 'ON', powerLimit: 7200, autoOffMinutes: 0, apiKey: 'mock-key-2' },
        { _id: '3', name: 'Smart Server Rack', status: 'OFF', powerLimit: 1500, autoOffMinutes: 5, apiKey: 'mock-key-3' }
      ] }));
      setDevices(res.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching devices:", error);
      setLoading(false);
    }
  };

  const toggleDevice = async (id, currentState) => {
    try {
      if (currentState === "ON") {
        await API.post(`/device/${id}/turn-off`).catch(e => console.log('API Failed but updating UI locally'));
        setDevices(devices.map(d => d._id === id ? { ...d, status: 'OFF' } : d));
      } else {
        await API.post(`/device/${id}/turn-on`).catch(e => console.log('API Failed but updating UI locally'));
        setDevices(devices.map(d => d._id === id ? { ...d, status: 'ON' } : d));
      }
    } catch (error) {
      console.error("Error toggling device:", error);
    }
  };

  const deleteDevice = async (id) => {
    if (!window.confirm("Are you sure you want to delete this device?")) return;
    try {
      await API.delete(`/device/${id}`).catch(e => console.log('API Failed but updating UI locally'));
      setDevices(devices.filter(d => d._id !== id));
    } catch (error) {
      console.error("Error deleting device:", error);
    }
  };

  const regenerateKey = async (id) => {
    if (!window.confirm("Regenerating the API key will immediately invalidate the old one. Continue?")) return;
    try {
      const res = await API.post(`/device/${id}/regenerate-key`).catch(e => ({ data: { apiKey: 'new-mock-key-' + Date.now() } }));
      setDevices(devices.map(d => d._id === id ? { ...d, apiKey: res.data.apiKey } : d));
    } catch (error) {
      console.error("Error regenerating key:", error);
    }
  };

  const addDevice = async (e) => {
    e.preventDefault();
    try {
      const res = await API.post('/device', newDevice).catch(e => ({ data: {
        _id: 'new-' + Date.now(),
        name: newDevice.name,
        powerLimit: newDevice.powerLimit,
        autoOffMinutes: newDevice.autoOffMinutes,
        status: 'OFF',
        apiKey: 'generated-key-' + Date.now()
      } }));
      setDevices([...devices, res.data]);
      setShowAddModal(false);
      setNewDevice({ name: '', powerLimit: 1000, autoOffMinutes: 5 });
    } catch (error) {
      console.error("Error adding device:", error);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <main className="pt-16 min-h-screen px-container-margin py-section-gap mx-auto bg-background text-on-background font-body-md">
        <div className="flex flex-col w-full gap-section-gap">
          <div className="flex items-end justify-between w-full">
            <div className="flex flex-col gap-unit">
              <span className="font-label-caps text-on-surface-variant tracking-widest text-primary">
                SYSTEM INVENTORY
              </span>
              <h1 className="font-display-lg text-on-surface">
                Connected Devices
              </h1>
            </div>
            <button onClick={() => setShowAddModal(true)} className="flex items-center gap-2 bg-vibrant-violet/10 text-vibrant-violet border border-vibrant-violet/30 px-6 py-3 rounded-full hover:bg-vibrant-violet hover:text-white transition-all duration-300 shadow-[0_0_15px_rgba(139,92,246,0.2)] hover:shadow-[0_0_25px_rgba(139,92,246,0.5)] group">
              <span className="material-symbols-outlined transition-transform duration-500">
                add
              </span>
              <span className="font-label-caps tracking-widest">
                ADD DEVICE
              </span>
            </button>
          </div>

          {showAddModal && (
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center">
              <div className="bg-surface-container border border-glass-stroke p-8 rounded-2xl w-full max-w-md shadow-2xl">
                <h2 className="text-xl font-title-md text-on-surface mb-6">Register New Device</h2>
                <form onSubmit={addDevice} className="flex flex-col gap-4">
                  <div>
                    <label className="block text-sm font-label-caps text-on-surface-variant mb-1">Device Name</label>
                    <input type="text" required value={newDevice.name} onChange={e => setNewDevice({...newDevice, name: e.target.value})} className="w-full bg-background border border-glass-stroke rounded p-2 text-on-surface" />
                  </div>
                  <div>
                    <label className="block text-sm font-label-caps text-on-surface-variant mb-1">Power Limit (Watts)</label>
                    <input type="number" required min="1" value={newDevice.powerLimit} onChange={e => setNewDevice({...newDevice, powerLimit: Number(e.target.value)})} className="w-full bg-background border border-glass-stroke rounded p-2 text-on-surface" />
                  </div>
                  <div>
                    <label className="block text-sm font-label-caps text-on-surface-variant mb-1">Auto-Off Minutes</label>
                    <input type="number" min="0" value={newDevice.autoOffMinutes} onChange={e => setNewDevice({...newDevice, autoOffMinutes: Number(e.target.value)})} className="w-full bg-background border border-glass-stroke rounded p-2 text-on-surface" />
                  </div>
                  <div className="flex justify-end gap-3 mt-6">
                    <button type="button" onClick={() => setShowAddModal(false)} className="px-4 py-2 rounded text-on-surface hover:bg-surface-dim transition-colors">Cancel</button>
                    <button type="submit" className="px-4 py-2 rounded bg-electric-blue text-surface font-label-caps">Create</button>
                  </div>
                </form>
              </div>
            </div>
          )}

          <div className="grid grid-cols-12 gap-gutter relative">
            <div className="col-span-12 flex flex-col gap-6">
              {devices.map((device, index) => (
                <div key={device._id} className="group relative z-10">
                  <div className="bg-surface-container-low/60 backdrop-blur-xl border border-glass-stroke rounded-3xl p-8 h-full flex flex-col justify-between overflow-hidden relative shadow-2xl">
                    <div className="flex justify-between items-start mb-8 relative z-10">
                      <div className="flex items-center gap-4">
                        <div className={`w-16 h-16 rounded-2xl bg-surface-container border border-glass-stroke flex items-center justify-center shadow-inner relative overflow-hidden ${device.status === 'ON' ? 'border-electric-blue/50 shadow-[0_0_15px_rgba(0,209,255,0.2)]' : ''}`}>
                          <div className={`absolute inset-0 bg-gradient-to-t ${device.status === 'ON' ? 'from-electric-blue/20' : 'from-surface-dim'} to-transparent opacity-50`}></div>
                          <span
                            className={`material-symbols-outlined text-3xl ${device.status === 'ON' ? 'text-electric-blue' : 'text-on-surface-variant'}`}
                            style={{ fontVariationSettings: "'FILL' 1" }}
                          >
                            settings_input_component
                          </span>
                        </div>
                        <div>
                          <h2 className="font-headline-lg text-on-surface">
                            {device.name}
                          </h2>
                          <p className="font-data-mono text-on-surface-variant flex items-center gap-2 mt-1">
                            <span className={`w-2 h-2 rounded-full shadow-[0_0_8px_rgba(0,209,255,0.8)] ${device.status === 'ON' ? 'bg-electric-blue animate-pulse' : 'bg-surface-dim'}`}></span>
                            API Key: {device.apiKey || 'Hidden'}
                          </p>
                        </div>
                      </div>
                      <div className="flex gap-3">
                        <span className={`px-4 py-1.5 rounded-full font-label-caps flex items-center gap-2 border ${device.status === 'ON' ? 'bg-electric-blue/10 text-electric-blue border-electric-blue/20' : 'bg-surface-container text-on-surface-variant border-glass-stroke'}`}>
                          <span className="material-symbols-outlined text-sm">
                            power_settings_new
                          </span>{" "}
                          {device.status === 'ON' ? 'ON' : 'OFF'}
                        </span>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-6 mb-8 relative z-10">
                      <div className="bg-surface-container/50 border border-glass-stroke rounded-2xl p-5 flex flex-col gap-2 hover:bg-surface-container/80 transition-colors">
                        <span className="font-label-caps text-on-surface-variant">
                          POWER LIMIT
                        </span>
                        <div className="flex items-baseline gap-1">
                          <span className={`font-display-lg ${device.status === 'ON' ? 'text-electric-blue' : 'text-on-surface-variant'}`}>
                            {device.powerLimit || 'N/A'}
                          </span>
                          <span className="font-title-md text-on-surface-variant">
                            W
                          </span>
                        </div>
                      </div>
                      <div className="bg-surface-container/50 border border-glass-stroke rounded-2xl p-5 flex flex-col gap-2 hover:bg-surface-container/80 transition-colors">
                        <span className="font-label-caps text-on-surface-variant">
                          AUTO-OFF TIMER
                        </span>
                        <div className="flex items-baseline gap-1">
                          <span className={`font-display-lg ${device.status === 'ON' ? 'text-vibrant-violet' : 'text-on-surface-variant'}`}>
                            {device.autoOffMinutes || '--'}
                          </span>
                          <span className="font-title-md text-on-surface-variant">
                            Mins
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center justify-between border-t border-glass-stroke pt-6 relative z-10">
                      <div className="flex items-center gap-2">
                        <button onClick={() => regenerateKey(device._id)} className="px-4 py-2 rounded-lg border border-glass-stroke text-on-surface-variant font-label-caps hover:bg-surface-container hover:text-white transition-colors flex items-center gap-2">
                          <span className="material-symbols-outlined text-sm">
                            refresh
                          </span>{" "}
                          REGENERATE KEY
                        </button>
                        <button onClick={() => deleteDevice(device._id)} className="px-4 py-2 rounded-lg border border-error-red/30 text-error-red font-label-caps hover:bg-error-red/10 transition-colors flex items-center gap-2">
                          <span className="material-symbols-outlined text-sm">
                            delete
                          </span>{" "}
                          DELETE
                        </button>
                      </div>
                      <div className="flex items-center gap-4">
                        <label className="relative inline-flex items-center cursor-pointer ml-4">
                          <input
                            checked={device.status === 'ON'}
                            onChange={() => toggleDevice(device._id, device.status)}
                            className="sr-only peer"
                            type="checkbox"
                          />
                          <div className="w-16 h-8 bg-surface-dim rounded-full peer peer-checked:after:translate-x-8 peer-checked:after:border-white after:content-[''] after:absolute after:top-[4px] after:left-[4px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-vibrant-violet shadow-[inset_0_2px_4px_rgba(0,0,0,0.4)] border border-glass-stroke"></div>
                        </label>
                      </div>
                    </div>
                  </div>
                </div>
              ))}

              {devices.length === 0 && (
                <div className="bg-surface-container-lowest border border-glass-stroke border-dashed rounded-3xl p-12 flex flex-col items-center justify-center text-center opacity-60">
                   <h3 className="font-title-md text-on-surface mb-2">No Devices Registered</h3>
                   <p className="font-body-md text-on-surface-variant">Click 'Add Device' to get started.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </Layout>
  );
}

export default Devices;
